)

// DEVDESK-142: :jobs on the activity column (Rule 125, "The activity column").

// ── Criterion 1: column 0 is datatable.IndicatorColumn at both levels ────────

func TestColumnZeroIsTheActivityColumnAtBothLevels(t *testing.T) {
	check := func(t *testing.T, name string, title string, sizing datatable.Sizing, minWidth int, hasIndicator, hasLess, hasSearch bool) {
		t.Helper()
		if title != "" {
			t.Errorf("%s: column 0 is titled %q, want untitled", name, title)
		}
		if sizing != datatable.SizingFixed || minWidth != datatable.IconColumnWidth {
			t.Errorf("%s: column 0 sizing/min = %v/%d, want SizingFixed/%d", name, sizing, minWidth, datatable.IconColumnWidth)
		}
		if !hasIndicator {
			t.Errorf("%s: column 0 is not built by datatable.IndicatorColumn (no Indicator)", name)
		}
		if hasLess || hasSearch {
			t.Errorf("%s: column 0 declares Less=%v Search=%v, want neither", name, hasLess, hasSearch)
		}
	}
	rc := runColumns()[0]
	check(t, "runs", rc.Title, rc.Sizing, rc.MinWidth, rc.Indicator != nil, rc.Less != nil, rc.Search != nil)
	ic := itemColumns()[0]
	check(t, "targets", ic.Title, ic.Sizing, ic.MinWidth, ic.Indicator != nil, ic.Less != nil, ic.Search != nil)
}

// ── Criterion 2: one glyph per state, and the State word follows the dot ─────

func TestEachRunStateMapsToItsOwnIndicator(t *testing.T) {
	col := runColumns()[runColumnState]
	if col.Indicator == nil {
		t.Fatal("the runs table has no activity column")
	}
	for _, tc := range []struct {
		name  string
		items []jobs.ItemState
		want  indicator.State
	}{
		{"queued", []jobs.ItemState{jobs.ItemQueued}, indicator.Queued},
		{"running", []jobs.ItemState{jobs.ItemRunning}, indicator.Running},
		{"done", []jobs.ItemState{jobs.ItemDone}, indicator.Done},
		{"failed", []jobs.ItemState{jobs.ItemFailed}, indicator.Failed},
	} {
		{Label: string(run.Kind) + " " + theme.IconChevronRight + " " + run.Label},
	}
	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, 1), width)
}

// status is the derived line, with no timer (Rule 128).
//
// The text is the count, asked for with no origin: this view launched none of
// it, so the detailed form would be a lie about ownership. The detail is the
// selected row's own sentence (DescribeRun, or DescribeItem at the target
// level); while a row is selected its dot moves, so the footer spinner is
// dropped.
func (m Model) status() sharedcomponents.Status {
	var st sharedcomponents.Status
	if p := jobs.Summarize(m.visibleRuns(), nil, 0); p.Running > 0 {
		st.Text = sharedcomponents.Plural(p.Running, "job", "jobs") + " running"
		if p.Stopping > 0 {
			st.Text += " · " + strconv.Itoa(p.Stopping) + " stopping"
		}
	}
	st.Detail = m.selectedDetail()
	st.Spinner = st.Text != "" && st.Detail.IsZero()
	return st
}

// selectedDetail is the sentence of the row under the cursor, zero when there
// is none.
func (m Model) selectedDetail() sharedcomponents.RowDetail {
	if m.level == levelItems {
		run, ok := m.openedRun()
		row, sel := m.itemTable.Selected()
		if !ok || !sel {
			return sharedcomponents.RowDetail{}
		}
		return sharedcomponents.DescribeItem(run.Kind, row.Item).Detail
	}
	m.failures = msg.Failures
	m.refreshRows()
	return m, nil
}

// handleFrameMsg takes the animation's frame: the blink phase of both tables,
// which they read at render, and the footer spinner. No row is rebuilt.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.runTable.SetBlinkPhase(msg.Blink)
	m.itemTable.SetBlinkPhase(msg.Blink)
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	return m, nil
}

// visibleRuns is what this view shows: the runs of the current context (D8).
// The table decides the order; this decides which exist.
func (m Model) visibleRuns() []jobs.Run {
	return jobs.FilterContext(m.runs, m.contextName)
}

