package workspaces

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/jobs"
)

// ── DEVDESK-139: the frame arrives in its own message ────────────────────────

// DEVDESK-144: a frame moves the blink phase and the footer spinner, never the
// text of a cell. The row says "syncing" with no frame in it.
func TestAFrameDoesNotChangeTheRowCells(t *testing.T) {
	m := running(t, loadedModel(t), jobs.KindSync, devdeskPath)
	nRuns := len(m.jobs)

	for _, frame := range []string{"X", "Y"} {
		m = feed(t, m, jobs.FrameMsg{Frame: frame, RenderedFrame: frame})
		if got := m.table.Items()[0].GitStatus; got != "syncing" {
			t.Errorf("Git Status = %q after frame %q, want %q unchanged", got, frame, "syncing")
		}
	}
	if len(m.jobs) != nRuns {
		t.Errorf("the held runs went from %d to %d on a frame", nRuns, len(m.jobs))
	}
}

func TestAFrameMovesTheFooterSpinner(t *testing.T) {
	m := running(t, loadedModel(t), jobs.KindSync, devdeskPath)

	// An idle row keeps the spinner; the running row's own dot moves instead.
	m = selectRow(t, m, "clean-repo")
	m = feed(t, m, jobs.FrameMsg{RenderedFrame: "<R1>"})

	if footer := m.RenderFooter(160); !strings.Contains(footer, "<R1>") {
		t.Errorf("the footer does not carry the new frame:\n%s", footer)
	}
}

// A frame is not a snapshot: it must not reset what the last ChangedMsg left.
func TestAFrameKeepsTheSnapshot(t *testing.T) {
	m := running(t, loadedModel(t), jobs.KindSync, devdeskPath)

	m = feed(t, m, jobs.FrameMsg{Frame: "X", RenderedFrame: "X"})

	if !m.syncing(devdeskPath) {
		t.Error("a frame made the running sync disappear from the view")
	}
	if got := len(jobs.Unfinished(m.jobs)); got != 1 {
		t.Errorf("%d unfinished runs held after a frame, want the 1 from the snapshot", got)
	}
}
		t.Errorf("footer height %d, want unchanged %d", m.GetFooterHeight(), base)
	}
	lines := strings.Split(m.RenderFooter(40), "\n")
	last := lines[len(lines)-1]
	if lipgloss.Width(last) > 40 {
		t.Errorf("info line is %d wide at 40: %q", lipgloss.Width(last), last)
	}
	if !strings.Contains(last, "/12") {
		t.Errorf("progress must survive truncation: %q", last)
	}
}

func jobsFrame(rendered string) jobs.FrameMsg {
	return jobs.FrameMsg{Frame: rendered, RenderedFrame: rendered, Blink: true}
}

func t0() time.Time { return time.Date(2026, 11, 1, 10, 0, 0, 0, time.UTC) }
	if !m.table.BlinkPhase() {
		t.Error("Blink=true did not turn the phase back on")
	}
	after := m.table.Items()
	if len(before) == 0 || len(before) != len(after) || &before[0] != &after[0] {
		t.Error("a frame rebuilt the rows; the phase is read at render")
	}
}

func TestAFrameStillFeedsTheFooterSpinner(t *testing.T) {
	m := withSnapshot(t, loadedModel(t), []jobs.Run{runningRun(jobs.KindScan, indRepo)}, nil)
	m = feed(t, m, jobs.FrameMsg{Frame: "ZZ", RenderedFrame: "FOOTERFRAME", Blink: true})
	if strings.Contains(m.Render(), "ZZ") {
		t.Error("the bare frame still reaches the table")
	}
	if !strings.Contains(m.RenderFooter(120), "FOOTERFRAME") {
		t.Skip("footer shows no spinner for this state; only the table side is asserted")
	}
}

func TestTheModelHoldsNoRowSpinnerFrame(t *testing.T) {
	if _, ok := reflect.TypeOf(Model{}).FieldByName("jobFrame"); ok {
		t.Error("Model still carries jobFrame; the phase lives in the table")
	}
}

func TestTheTableFillsTheViewportAt60Columns(t *testing.T) {
	m := feed(t, loadedModel(t), tea.WindowSizeMsg{Width: 60, Height: 30})
	if got := m.table.RenderedWidth(); got != 58 {
		t.Errorf("RenderedWidth = %d, want 58", got)
	}
// error still wins over it — it is the thing that needs answering.
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, m.status())
}

// status is the derived footer line: the selected row's own sentence (what it
// is doing, or the failure it remembers), then the batch progress. A row with a
// running or queued detail has a dot that already moves, so the footer spinner is dropped.
func (m Model) status() sharedcomponents.Status {
	st := sharedcomponents.Status{Text: m.jobsStatusLine()}
	moving := false
	if row, ok := m.table.Selected(); ok {
		a := m.rowActivity(row.Entry)
		st.Detail = a.Detail
		moving = a.State == indicator.Running || a.State == indicator.Queued
	}
	// Only a detail whose dot moves replaces the spinner; a failed row's is fixed.
	st.Spinner = m.anyWorking() && (!moving || st.Detail.IsZero())
	return st
}

// renderTabBar renders the breadcrumb tab bar at the bottom of the viewport
func (m Model) renderTabBar() string {
	tabs := []theme.TabItem{{Label: theme.IconHome + " home"}}

	// Add navigation stack entries as tabs
	for _, path := range m.navigationStack {
		tabs = append(tabs, theme.TabItem{Label: theme.IconDirectory + " " + pathBaseName(path)})
	}

	// Add current directory as last tab (if not at root)
	if m.currentPath != "" {
		tabs = append(tabs, theme.TabItem{Label: theme.IconDirectory + " " + pathBaseName(m.currentPath)})
	}

	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, m.activeTabIndex), m.width)
