// is carried across a reload, and a scan started from ws or the images tab
// marks the same row.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context
	m.setInventory(m.inventory.Items())
	return m, nil
}

// handleFrameMsg takes the animation's blink phase, which the table reads at
// render; no row is rebuilt. The footer frame is the router's only while the
// view's own load or remediation spinner is not running.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.inventory.SetBlinkPhase(msg.Blink)
	if !m.spinnerAlive() {
		m.footer.SetSpinnerFrame(msg.RenderedFrame)
	}
	return m, nil
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by. Tests only.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"sec/inventory": &m.inventory}
}
	// what the footer is for, and a stage that failed still shows on the others.
	if status, ok := m.remediationStatus(); ok {
		return status
	}
	if m.state != StateResults || m.result == nil || len(m.result.Errors) == 0 {
		return sharedcomponents.Status{}
	}
	return sharedcomponents.Status{
		Text:  failedStages(m.result.Errors) + " — check logs",
		Level: sharedcomponents.LevelError,
	}
}

// inventoryStatus is the inventory footer: the selected row's own activity
// (its detail), composed with the batch progress or, while the caches are
// read, the load text. The load no longer hides the row: a failed row still
// says so under a ctrl+r.
func (m Model) inventoryStatus() sharedcomponents.Status {
	st := sharedcomponents.Status{Text: sharedcomponents.JobsStatusLine(m.jobs, command.ViewSecurity)}
	if m.inventoryLoading {
		st.Text = "Loading scan inventory..."
	}
	moving := false
	if row, ok := m.inventory.Selected(); ok {
		a := m.rowActivity(row)
		st.Detail = a.Detail
		moving = a.State == indicator.Running || a.State == indicator.Queued
	}
	// Only a detail whose dot moves replaces the spinner; a failed row's is fixed.
	st.Spinner = m.inventoryLoading ||
		(len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero()))
	return st
}

// failedStages names what failed, reading the "<stage>: <reason>" that
// scan.recordStageError writes. The reason stays in the log: a footer is one
// line, and a tool's stderr is not.
func failedStages(errs []string) string {
	stages := make([]string, 0, len(errs))
	for _, e := range errs {
		stage := e
		if idx := strings.Index(e, ": "); idx != -1 {
			stage = e[:idx]
		}
		stages = append(stages, stage)
	}
	return strings.Join(stages, ", ") + " failed"
}

// renderTabs renders the tab bar
func (m Model) renderTabs() string {
package security

import (
	"testing"

